from tinydb import TinyDB, where
from tinydb.storages import MemoryStorage

db = TinyDB(storage=MemoryStorage)
db.insert_multiple([
    {'name': 'Alice'}, {'name': 'Alan'}, {'name': 'alice'},
    {'name': 5}, {'name': None}, {'x': 1}, {'name': ''}
])
print('startswith Al:', [d['name'] for d in db.search(where('name').startswith('Al'))])

